  const registry = join(dir, "registry.json"), count = join(dir, "calls.txt"), journal = join(dir, "journal.jsonl"), socket = join(dir, "service.sock");
  writeFileSync(registry, JSON.stringify({
    concurrency: 2,
    attempts: 2,
    endpoints: endpoints.map(({ id, model, cost = 1 }) => ({
      id,
      type: "harness",
      command: "helper.mjs",
      model,
      concurrency: 1,
      profile: { capabilities: ["text"], expectedLatencyMs: model === "slow" ? 500 : 1, successPrior: 0.99, cost: { unit: "test", dispatch: 0, inference: cost, verification: 0, scarcity: 0 } }
