  return { dir, registry, count, journal, socket, dispose: () => rmSync(dir, { recursive: true, force: true }) };
}

function startService(fix, extra = []) {
  const child = spawn(process.execPath, [SERVICE, "--registry", fix.registry, "--journal", fix.journal, "--socket", fix.socket, ...extra], {
    cwd: fix.dir,
