test("independent clients share global scheduling without receiving each other's results", async () => {
  const fix = fixture([{ id: "slow", model: "slow" }, { id: "fast", model: "fast" }]);
  const run = startService(fix, ["--concurrency", "2"]);
  try {
    assert.equal(await run.ready, true, run.stderr());
    const [slow, fast] = await Promise.all([exchange(fix.socket, [job("colony-a", "slow")]), exchange(fix.socket, [job("colony-b", "fast")])]);
    assert.deepEqual(slow.map((record) => record.id), ["colony-a"]);
    assert.deepEqual(fast.map((record) => record.id), ["colony-b"]);
    assert.equal(slow[0].text, "helper:slow");
    assert.equal(fast[0].text, "helper:fast");
    assert.deepEqual(lines(readFileSync(fix.journal, "utf8")).map((record) => record.id), ["colony-b", "colony-a"]);
  } finally { assert.equal((await stopService(run)).code, 0); fix.dispose(); }
});

