  const fix = fixture([{ id: "only", model: "slow" }]);
  const run = startService(fix);
  try {
    assert.equal(await run.ready, true, run.stderr());
    const abandoned = connect(fix.socket);
    await new Promise((resolveConnect, rejectConnect) => { abandoned.once("connect", resolveConnect); abandoned.once("error", rejectConnect); });
    abandoned.write(`${JSON.stringify(job("durable-after-disconnect"))}\n`);
    await waitFor(() => existsSync(fix.count), "provider invocation");
    abandoned.destroy();
    await waitFor(() => existsSync(fix.journal) && readFileSync(fix.journal, "utf8").includes("durable-after-disconnect"), "durable settlement");
    const replay = await exchange(fix.socket, [{ type: "InferenceResultQuery", id: "durable-after-disconnect" }]);
    assert.equal(replay[0].text, "helper:slow");
    assert.equal(replay[0].scheduler.replayed, true);
    assert.equal(readFileSync(fix.count, "utf8").trim().split("\n").length, 1);
  } finally { assert.equal((await stopService(run)).code, 0); fix.dispose(); }
});

test("socket clients cannot shut down the broker and malformed or oversized lines stay contained", async () => {
