test("SIGTERM stops admission, drains accepted work, and removes explicit socket ownership", async () => {
  const fix = fixture([{ id: "only", model: "slow" }]);
  const run = startService(fix);
  try {
    assert.equal(await run.ready, true, run.stderr());
    const result = exchange(fix.socket, [job("drained")]);
    await waitFor(() => existsSync(fix.count), "provider invocation");
    run.child.kill("SIGTERM");
    const records = await result, closed = await run.closed;
    assert.equal(closed.code, 0, closed.stderr);
    assert.equal(records[0].text, "helper:slow");
    assert(!existsSync(fix.socket));
    assert(!existsSync(`${fix.journal}.lock`));
  } finally { await stopService(run); fix.dispose(); }
});

test("request client streams jobs into the persistent service", async () => {
